public static NVLeaveBalanceDetailsTmp balanceByLeaveType(HcmWorkerRecId _worker, 
    date _asOfDate = dateMax(),
    LeaveTypeRecId _leaveType = 0,
    date _startDate = dateMax(),
    real _totalRequestedDays = 0,
    LeaveRequestRecId _requestToIgnore = 0)
{
    date asOfDate       = _asOfDate;
    date startDate      = _startDate == dateMax()? _asOfDate: _startDate - 1;

    NVLeaveBalanceDetailsTmp    detailsTmp;
    LeaveBankTransaction        transaction;
    ttsbegin;
    /// Get all details by year and category
    while select Worker, LeaveType, NVLeaveCategory, NVTransactionYear, maxof(LeavePlan), sum(Amount) from transaction
        group by transaction.Worker,
            transaction.LeaveType, 
            transaction.NVLeaveCategory,
            transaction.NVTransactionYear
        where transaction.Worker                == _worker
            && transaction.TransactionDate      <= asOfDate
            && transaction.NVTransactionYear    != 0
            && (_leaveType == 0 || transaction.LeaveType == _leaveType)
            && transaction.TransactionType != LeaveTransactionType::Grant
    {
        //if(transaction.Amount != 0)
        {
            NVLeavePlanLeaveBalancePolicy balancePolicy = NVLeavePlanLeaveBalancePolicy::findByPlan(transaction.LeavePlan, transaction.NVLeaveCategory);

            detailsTmp.Worker                   = transaction.Worker;
            detailsTmp.LeaveType                = transaction.LeaveType;
            detailsTmp.Category                 = transaction.NVLeaveCategory;
            detailsTmp.TransactionYear          = transaction.NVTransactionYear;
            detailsTmp.Balance                  = transaction.Amount;
            detailsTmp.DeductPriority           = balancePolicy.Priority;
            detailsTmp.IncludeBalanceInBase     = detailsTmp.Category == NVLeaveCategory::None? NoYes::No: balancePolicy.IncludeBalanceInBase;

            detailsTmp.insert();
        }
    }

    /// Sum up the values where balance needs to be included in base of other categories
    select sum(Balance) from detailsTmp
        where detailsTmp.IncludeBalanceInBase == NoYes::Yes;
    LeaveAmountUnsigned baseAdditional = detailsTmp.Balance;
    NVLeaveBalanceDetailsTmp details;
    while select detailsTmp
        where detailsTmp.IncludeBalanceInBase == NoYes::No
    {
        details.Worker                  = detailsTmp.Worker;
        details.LeaveType               = detailsTmp.LeaveType;
        details.Category                = detailsTmp.Category;
        details.TransactionYear         = detailsTmp.TransactionYear;
        details.Balance                 = detailsTmp.Balance;
        details.DeductPriority          = detailsTmp.DeductPriority;

        if(details.Category == NVLeaveCategory::None)
        {
            details.Balance             = details.Balance + baseAdditional;
        }

        details.insert();
    }

    /// Get used details for in review request
    NVLeaveBalanceDetailsTmp    leaveTypeGroup;
    insert_recordset leaveTypeGroup (LeaveType)
        select LeaveType from details
            group by details.LeaveType;
    while select leaveTypeGroup
    {
        LeaveAmountUnsigned inReviewRequest = NVLeaveBalanceDetailsTmp::inReviewByLeaveType(_worker, startDate, _leaveType);
        if(inReviewRequest > 0)
        {
            select details
            order details.TransactionYear, details.DeductPriority
            where details.LeaveType  == leaveTypeGroup.LeaveType;

            while(inReviewRequest > 0 && details)
            {
                if(details.Balance > 0)
                {
                    details.selectForUpdate(true);
                    details.InReviewRequest = details.Balance >= inReviewRequest? inReviewRequest: inReviewRequest - details.Balance;
                    details.update();

                    inReviewRequest -= details.InReviewRequest;
                }
                next details;
            }
        }
    }


    /// Get used details for current request
    if(_totalRequestedDays != 0 )
    {
        LeaveAmountUnsigned totalRequestedDays = _totalRequestedDays;
        select details
            order details.TransactionYear, details.DeductPriority
            where details.LeaveType  == _leaveType;

        while(totalRequestedDays > 0 && details)
        {
            LeaveAmountUnsigned unusedBalance = details.Balance - details.InReviewRequest;
            if(unusedBalance > 0)
            {
                details.selectForUpdate(true);
                details.CurrentRequest = unusedBalance >= totalRequestedDays? totalRequestedDays: unusedBalance;
                details.update();

                totalRequestedDays -= details.CurrentRequest;
            }
            next details;
        }
    }
    ttscommit;

    return details;
}

public static LeaveAmountUnsigned inReviewByLeaveType(HcmWorkerRecId _worker, date _asOfDate, LeaveTypeRecId _leaveType)
{
    LeaveRequest            request;
    LeaveRequestDetail      requestDetails;

    select count(RecId) from request
        where request.Worker            == _worker
            && (request.Status          == LeaveRequestApprovalStatus::InReview
                || request.Status       == LeaveRequestApprovalStatus::Submitted)
        join sum(Amount) from requestDetails
            where requestDetails.Request    == request.RecId
                && requestDetails.LeaveType == _leaveType
                && requestDetails.LeaveDate <= _asOfDate;

    return requestDetails.Amount;
}
